package com.dukaops.backend.reports;

import java.math.BigDecimal; import java.time.Instant; import java.util.*;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import jakarta.persistence.EntityManager; import jakarta.persistence.PersistenceContext;
import com.dukaops.backend.auth.TenantUserPrincipal;

@Service
public class ReportsService {
 @PersistenceContext private EntityManager em;
 private Map<String,Object> row(TenantUserPrincipal p, UUID branch, Instant from, Instant to){ Map<String,Object> x=new HashMap<>(); x.put("tenantId",p.getTenantId()); x.put("branchId",branch); x.put("from",from); x.put("to",to); return x; }
 private List<?> query(String sql, Map<String,Object> params){var q=em.createNativeQuery(sql);params.forEach((k,v)->{if(v!=null)q.setParameter(k,v);});return q.getResultList();}
 @Transactional(readOnly=true) public Map<String,Object> overview(TenantUserPrincipal p,UUID b,Instant f,Instant t){var x=row(p,b,f,t);var r=scalar("select coalesce(sum(total_amount),0),count(*) from sales_orders where tenant_id=:tenantId and status='COMPLETED' and (:branchId is null or branch_id=:branchId) and (:from is null or created_at>=:from) and (:to is null or created_at<:to)",x);var v=(Object[])r.get(0);Map<String,Object> out=new LinkedHashMap<>();out.put("revenue",v[0]);out.put("completedSales",v[1]);out.put("totalOrders",scalar("select count(*) from sales_orders where tenant_id=:tenantId and (:branchId is null or branch_id=:branchId) and (:from is null or created_at>=:from) and (:to is null or created_at<:to)",x).get(0));out.put("averageSaleValue",((Number)v[1]).longValue()==0?BigDecimal.ZERO:new BigDecimal(v[0].toString()).divide(BigDecimal.valueOf(((Number)v[1]).longValue()),2,java.math.RoundingMode.HALF_UP));out.put("activeProducts",scalar("select count(*) from products where tenant_id=:tenantId and status='ACTIVE'",x).get(0));out.put("lowStockProducts",scalar("select count(*) from stock_levels where tenant_id=:tenantId and quantity<=reorder_level and (:branchId is null or branch_id=:branchId)",x).get(0));out.put("customers",scalar("select count(*) from customers where tenant_id=:tenantId and status='ACTIVE'",x).get(0));return out;}
 @Transactional(readOnly=true) public Map<String,Object> sales(TenantUserPrincipal p,UUID b,Instant f,Instant t){var x=row(p,b,f,t);Map<String,Object> out=new LinkedHashMap<>();out.put("summary",overview(p,b,f,t));out.put("byDay",query("select date_trunc('day',created_at),coalesce(sum(total_amount),0),count(*) from sales_orders where tenant_id=:tenantId and status='COMPLETED' and (:branchId is null or branch_id=:branchId) and (:from is null or created_at>=:from) and (:to is null or created_at<:to) group by 1 order by 1",x));out.put("byPaymentMethod",query("select p.method,coalesce(sum(p.amount),0),count(*) from sales_payments p join sales_orders o on o.id=p.order_id where p.tenant_id=:tenantId and o.status='COMPLETED' and (:branchId is null or o.branch_id=:branchId) and (:from is null or o.created_at>=:from) and (:to is null or o.created_at<:to) group by p.method",x));out.put("transactions",query("select id,customer_name,status,total_amount,created_at,branch_id from sales_orders where tenant_id=:tenantId and (:branchId is null or branch_id=:branchId) and (:from is null or created_at>=:from) and (:to is null or created_at<:to) order by created_at desc limit 100",x));return out;}
 @Transactional(readOnly=true) public Map<String,Object> inventory(TenantUserPrincipal p,UUID b){var x=row(p,b,null,null);Map<String,Object> out=new LinkedHashMap<>();out.put("stock",query("select branch_id,product_id,quantity,reorder_level from stock_levels where tenant_id=:tenantId and (:branchId is null or branch_id=:branchId) order by quantity",x));out.put("movements",query("select id,branch_id,product_id,movement_type,quantity_change,quantity_after,created_at from stock_movements where tenant_id=:tenantId and (:branchId is null or branch_id=:branchId) order by created_at desc limit 100",x));return out;}
 @Transactional(readOnly=true) public Map<String,Object> products(TenantUserPrincipal p,UUID b,Instant f,Instant t){var x=row(p,b,f,t);Map<String,Object> out=new LinkedHashMap<>();out.put("bestSelling",query("select i.product_id,sum(i.quantity),sum(i.line_total) from sales_order_items i join sales_orders o on o.id=i.order_id where i.tenant_id=:tenantId and o.status='COMPLETED' and (:branchId is null or o.branch_id=:branchId) and (:from is null or o.created_at>=:from) and (:to is null or o.created_at<:to) group by i.product_id order by sum(i.quantity) desc limit 20",x));return out;}
 @Transactional(readOnly=true) public Map<String,Object> customers(TenantUserPrincipal p){Map<String,Object> o=new LinkedHashMap<>();o.put("total",scalar("select count(*) from customers where tenant_id=:tenantId",row(p,null,null,null)).get(0));o.put("active",scalar("select count(*) from customers where tenant_id=:tenantId and status='ACTIVE'",row(p,null,null,null)).get(0));return o;}
 @Transactional(readOnly=true) public Map<String,Object> suppliers(TenantUserPrincipal p){Map<String,Object> o=new LinkedHashMap<>();o.put("total",scalar("select count(*) from suppliers where tenant_id=:tenantId",row(p,null,null,null)).get(0));o.put("active",scalar("select count(*) from suppliers where tenant_id=:tenantId and status='ACTIVE'",row(p,null,null,null)).get(0));return o;}
 private List<?> scalar(String sql,Map<String,Object> p){return query(sql,p);} public String export(TenantUserPrincipal p,String type,UUID b){if(!"sales".equalsIgnoreCase(type))return "type,message\n"+safe(type)+",No export data available\n";var rows=sales(p,b,null,null).get("transactions");StringBuilder s=new StringBuilder("id,customer,status,total,createdAt,branchId\n");for(Object r: (List<?>)rows){Object[] a=(Object[])r;for(int i=0;i<a.length;i++){if(i>0)s.append(',');s.append(safe(a[i]));}s.append('\n');}return s.toString();}private String safe(Object v){String s=String.valueOf(v==null?"":v);if(s.startsWith("=")||s.startsWith("+")||s.startsWith("-")||s.startsWith("@"))s="'"+s;return '"'+s.replace("\"","\"\"")+'"';}
}
